package com.example.starter.domain;

import com.example.starter.support.ApiException;

import java.util.List;

/**
 * 目标平台相关常量与校验。
 *
 * <p>平台元素格式固定为 {@code os/arch}（os、arch 均非空白且不含 '/'），
 * 每个制品版本最多声明 10 项；也允许只含 {@link #ANY} 表示全平台。
 * {@code ANY} 与具体平台不能混填。
 */
public final class Platforms {

    /** 全平台通配：制品支持任意目标平台。 */
    public static final String ANY = "ANY";

    /** 单个制品版本允许声明的平台数量上限。 */
    public static final int MAX_PLATFORMS = 10;

    private Platforms() {
    }

    /**
     * 校验登记请求中的平台集合，返回不可变副本；null 或空按兼容规则视为 {@code [ANY]}。
     *
     * @throws ApiException 400 当格式非法、数量超限或 ANY 与具体平台混填
     */
    public static List<String> normalize(List<String> platforms) {
        if (platforms == null || platforms.isEmpty()) {
            return List.of(ANY);
        }
        if (platforms.size() > MAX_PLATFORMS) {
            throw ApiException.badRequest("每个制品版本最多声明 " + MAX_PLATFORMS + " 个平台");
        }
        java.util.TreeSet<String> normalized = new java.util.TreeSet<>();
        boolean hasAny = false;
        for (String raw : platforms) {
            if (raw == null || raw.isBlank()) {
                throw ApiException.badRequest("平台不能为空");
            }
            String p = raw.trim();
            if (ANY.equals(p)) {
                hasAny = true;
                normalized.add(p);
                continue;
            }
            String[] parts = p.split("/", -1);
            if (parts.length != 2 || parts[0].isBlank() || parts[1].isBlank()
                    || parts[0].contains(" ") || parts[1].contains(" ")) {
                throw ApiException.badRequest("平台格式必须为 os/arch: " + p);
            }
            normalized.add(p);
        }
        if (hasAny && normalized.size() > 1) {
            throw ApiException.badRequest("ANY 不能与具体平台混合声明");
        }
        return List.copyOf(normalized);
    }

    /**
     * 校验锁定请求的目标平台：必填，格式为 {@code os/arch}，不允许 ANY。
     *
     * @throws ApiException 400 当缺失或格式非法
     */
    public static String validateTarget(String targetPlatform) {
        if (targetPlatform == null || targetPlatform.isBlank()) {
            throw ApiException.badRequest("targetPlatform 不能为空");
        }
        String p = targetPlatform.trim();
        if (ANY.equals(p)) {
            throw ApiException.badRequest("targetPlatform 必须为具体平台 os/arch，不能为 ANY");
        }
        String[] parts = p.split("/", -1);
        if (parts.length != 2 || parts[0].isBlank() || parts[1].isBlank()
                || parts[0].contains(" ") || parts[1].contains(" ")) {
            throw ApiException.badRequest("targetPlatform 格式必须为 os/arch: " + p);
        }
        return p;
    }
}

